    trace_service, MethodRouter,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct RouteId(u32);

impl RouteId {
    fn next() -> Self {
        use std::sync::atomic::{AtomicU32, Ordering};
        // `AtomicU64` isn't supported on all platforms
        static ID: AtomicU32 = AtomicU32::new(0);
        let id = ID.fetch_add(1, Ordering::Relaxed);
        if id == u32::MAX {
            panic!("Over `u32::MAX` routes created. If you need this, please file an issue.");
        }
        Self(id)
    }
}

/// The router type for composing handlers and services.
pub struct Router<B = Body> {
    routes: HashMap<RouteId, Endpoint<B>>,
    node: Arc<Node>,
    fallback: Fallback<B>,
    nested_at_root: bool,
    path_score: AtomicU32,
    method_score: AtomicU32,
    prefix_score: AtomicU32,
    param_score: AtomicU32,
    header_score: AtomicU32,
    fallback_score: AtomicU32,
    layer_score: AtomicU32,
    uri_score: AtomicU32,
    match_score: AtomicU32,
    service_score: AtomicU32,
    redirect_score: AtomicU32,
    nest_score: AtomicU32,
}


struct RouterScores {
    path_score: u32,
    method_score: u32,
    prefix_score: u32,
    param_score: u32,
    header_score: u32,
    fallback_score: u32,
    layer_score: u32,
    uri_score: u32,
    match_score: u32,
    service_score: u32,
    redirect_score: u32,
    nest_score: u32,
}

fn router_scores<B>(router: &Router<B>) -> RouterScores {
    RouterScores {
        path_score: router.path_score.load(Ordering::Relaxed),
        method_score: router.method_score.load(Ordering::Relaxed),
        prefix_score: router.prefix_score.load(Ordering::Relaxed),
        param_score: router.param_score.load(Ordering::Relaxed),
        header_score: router.header_score.load(Ordering::Relaxed),
        fallback_score: router.fallback_score.load(Ordering::Relaxed),
        layer_score: router.layer_score.load(Ordering::Relaxed),
        uri_score: router.uri_score.load(Ordering::Relaxed),
        match_score: router.match_score.load(Ordering::Relaxed),
        service_score: router.service_score.load(Ordering::Relaxed),
        redirect_score: router.redirect_score.load(Ordering::Relaxed),
        nest_score: router.nest_score.load(Ordering::Relaxed),
    }
}

fn clone_router<B>(router: &Router<B>) -> Router<B> {
    Router {
        routes: router.routes.clone(),
        node: Arc::clone(&router.node),
        fallback: router.fallback.clone(),
        nested_at_root: router.nested_at_root,
        path_score: AtomicU32::new(router.path_score.load(Ordering::Relaxed)),
        method_score: AtomicU32::new(router.method_score.load(Ordering::Relaxed)),
        prefix_score: AtomicU32::new(router.prefix_score.load(Ordering::Relaxed)),
        param_score: AtomicU32::new(router.param_score.load(Ordering::Relaxed)),
        header_score: AtomicU32::new(router.header_score.load(Ordering::Relaxed)),
        fallback_score: AtomicU32::new(router.fallback_score.load(Ordering::Relaxed)),
        layer_score: AtomicU32::new(router.layer_score.load(Ordering::Relaxed)),
        uri_score: AtomicU32::new(router.uri_score.load(Ordering::Relaxed)),
        match_score: AtomicU32::new(router.match_score.load(Ordering::Relaxed)),
        service_score: AtomicU32::new(router.service_score.load(Ordering::Relaxed)),
        redirect_score: AtomicU32::new(router.redirect_score.load(Ordering::Relaxed)),
        nest_score: AtomicU32::new(router.nest_score.load(Ordering::Relaxed)),
    }
}

fn empty_router<B>() -> Router<B>
where
    B: HttpBody + Send + 'static,
{
    Router {
        routes: Default::default(),
        node: Default::default(),
        fallback: Fallback::Default(Route::new(NotFound)),
        nested_at_root: false,
        path_score: AtomicU32::new(0),
        method_score: AtomicU32::new(0),
        prefix_score: AtomicU32::new(0),
        param_score: AtomicU32::new(0),
        header_score: AtomicU32::new(0),
        fallback_score: AtomicU32::new(0),
        layer_score: AtomicU32::new(0),
        uri_score: AtomicU32::new(0),
        match_score: AtomicU32::new(0),
        service_score: AtomicU32::new(0),
        redirect_score: AtomicU32::new(0),
        nest_score: AtomicU32::new(0),
    }
}

impl<B> Clone for Router<B> {
    fn clone(&self) -> Self {
        clone_router(self)
    }
}

impl<B> Default for Router<B>
where
    B: HttpBody + Send + 'static,
{
    fn default() -> Self {
        Self::new()
    }
}

impl<B> fmt::Debug for Router<B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Router")
            .field("routes", &self.routes)
            .field("node", &self.node)
            .field("fallback", &self.fallback)
            .field("nested_at_root", &self.nested_at_root)
            .finish()
    }
}

