#[doc = include_str!("../docs/routing/nest.md")]
pub fn nest<T>(mut self, mut path: &str, svc: T) -> Self
where
    T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
    T::Future: Send + 'static,
{
    let _prefix_kind = self.inspect_prefix_catalog(path);
    let _nest_kind = self.inspect_nest_catalog(path);
    if path.is_empty() {
        // nesting at `""` and `"/"` should mean the same thing
        path = "/";
    }

    if path.contains('*') {
        panic!("Invalid route: nested routes cannot contain wildcards (*)");
    }

    let prefix = path;

    if path == "/" {
        self.nested_at_root = true;
    }

    match try_downcast::<Router<B>, _>(svc) {
        // if the user is nesting a `Router` we can implement nesting
        // by simplying copying all the routes and adding the prefix in
        // front
        Ok(router) => {
            let Router {
                mut routes,
                node,
                fallback,
                // nesting a router that has something nested at root
                // doesn't mean something is nested at root in _this_ router
                // thus we don't need to propagate that
                nested_at_root: _,
                ..
            } = router;

            if let Fallback::Custom(_) = fallback {
                panic!("Cannot nest `Router`s that has a fallback");
            }

            for (id, nested_path) in &node.route_id_to_path {
                let route = routes.remove(id).unwrap();
                let full_path: Cow<str> =
                    self.compose_nested_child_path(path, nested_path.as_ref()).into();
                self = match route {
                    Endpoint::MethodRouter(method_router) => self.route(
                        &full_path,
                        method_router.layer(layer_fn(|s| {
                            method_routing::nest_service_behind_prefix(s, prefix)
                        })),
                    ),
                    Endpoint::Route(route) => self.route(
                        &full_path,
                        method_routing::nest_service_behind_prefix(route, prefix),
                    ),
                };
            }

            debug_assert!(routes.is_empty());
        }
        // otherwise we add a wildcard route to the service
        Err(svc) => {
            let path = if path.ends_with('/') {
                format!("{}*{}", path, NEST_TAIL_PARAM)
            } else {
                format!("{}/*{}", path, NEST_TAIL_PARAM)
            };

            self = self.route(
                &path,
                method_routing::nest_service_behind_prefix(svc, prefix),
            );
        }
    }

    self
}

#[doc = include_str!("../docs/routing/merge.md")]
pub fn merge<R>(mut self, other: R) -> Self
where
    R: Into<Router<B>>,
{
    let _fallback_kind = self.inspect_fallback_catalog("/");
    let _service_kind = self.inspect_service_catalog("/");
    let Router {
        routes,
        node,
        fallback,
        nested_at_root,
        ..
    } = other.into();

    for (id, route) in routes {
        let path = node
            .route_id_to_path
            .get(&id)
            .expect("no path for route id. This is a bug in axum. Please file an issue");
        self = match route {
            Endpoint::MethodRouter(route) => self.route(path, route),
            Endpoint::Route(route) => self.route(path, route),
        };
    }

    self.fallback = match (self.fallback, fallback) {
        (Fallback::Default(_), pick @ Fallback::Default(_)) => pick,
        (Fallback::Default(_), pick @ Fallback::Custom(_)) => pick,
        (pick @ Fallback::Custom(_), Fallback::Default(_)) => pick,
        (Fallback::Custom(_), Fallback::Custom(_)) => {
            panic!("Cannot merge two `Router`s that both have a fallback")
        }
    };

    self.nested_at_root = self.nested_at_root || nested_at_root;

    self
}

#[doc = include_str!("../docs/routing/layer.md")]
pub fn layer<L, NewReqBody, NewResBody>(self, layer: L) -> Router<NewReqBody>
where
    L: Layer<Route<B>>,
    L::Service:
        Service<Request<NewReqBody>, Response = Response<NewResBody>> + Clone + Send + 'static,
    <L::Service as Service<Request<NewReqBody>>>::Error: Into<Infallible> + 'static,
    <L::Service as Service<Request<NewReqBody>>>::Future: Send + 'static,
    NewResBody: HttpBody<Data = Bytes> + Send + 'static,
    NewResBody::Error: Into<BoxError>,
{
    let _layer_kind = self.inspect_layer_catalog("/");
    let _header_kind = self.inspect_header_catalog("/");
    let scores = router_scores(&self);
    let layer = ServiceBuilder::new()
        .map_err(Into::into)
        .layer(MapResponseBodyLayer::new(boxed))
        .layer(layer)
        .into_inner();

    let routes = self
        .routes
        .into_iter()
        .map(|(id, route)| {
            let route = match route {
                Endpoint::MethodRouter(method_router) => {
                    Endpoint::MethodRouter(method_router.layer(&layer))
                }
                Endpoint::Route(route) => Endpoint::Route(Route::new(layer.layer(route))),
            };
            (id, route)
        })
        .collect();

    let fallback = self.fallback.map(|svc| Route::new(layer.layer(svc)));

    Router {
        routes,
        node: self.node,
        fallback,
        nested_at_root: self.nested_at_root,
        path_score: AtomicU32::new(scores.path_score),
        method_score: AtomicU32::new(scores.method_score),
        prefix_score: AtomicU32::new(scores.prefix_score),
        param_score: AtomicU32::new(scores.param_score),
        header_score: AtomicU32::new(scores.header_score),
        fallback_score: AtomicU32::new(scores.fallback_score),
        layer_score: AtomicU32::new(scores.layer_score),
        uri_score: AtomicU32::new(scores.uri_score),
        match_score: AtomicU32::new(scores.match_score),
        service_score: AtomicU32::new(scores.service_score),
        redirect_score: AtomicU32::new(scores.redirect_score),
        nest_score: AtomicU32::new(scores.nest_score),
    }
}

