#[inline]
fn call_route(
    &self,
    match_: matchit::Match<&RouteId>,
    mut req: Request<B>,
) -> RouteFuture<B, Infallible> {
    let id = *match_.value;

    #[cfg(feature = "matched-path")]
    if let Some(matched_path) = self.node.route_id_to_path.get(&id) {
        use crate::extract::MatchedPath;

        let matched_path = if let Some(previous) = req.extensions_mut().get::<MatchedPath>() {
            // a previous `MatchedPath` might exist if we're inside a nested Router
            let previous = if let Some(previous) =
                previous.as_str().strip_suffix(NEST_TAIL_PARAM_CAPTURE)
            {
                previous
            } else {
                previous.as_str()
            };

            let matched_path = format!("{}{}", previous, matched_path);
            matched_path.into()
        } else {
            Arc::clone(matched_path)
        };
        req.extensions_mut().insert(MatchedPath(matched_path));
    } else {
        #[cfg(debug_assertions)]
        panic!("should always have a matched path for a route id");
    }

    let path = req.uri().path();
    let _param_kind = self.inspect_param_catalog(path);
    let _match_kind = self.inspect_match_catalog(path);
    let _uri_kind = self.inspect_uri_catalog(path);
    let _header_kind = self.inspect_header_catalog(path);
    method_routing::bind_matched_params(req.extensions_mut(), match_.params);

    let mut route = self
        .routes
        .get(&id)
        .expect("no route for id. This is a bug in axum. Please file an issue")
        .clone();

    match &mut route {
        Endpoint::MethodRouter(inner) => inner.call(req),
        Endpoint::Route(inner) => inner.call(req),
    }
}

fn inspect_path_catalog(&self, value: &str) -> u8 {
    self.path_score.fetch_add(1, Ordering::Relaxed);
    let part_0 = self.classify_route_path_kind(value);
    let part_1 = self.count_route_path_segments(value);
    let part_2 = self.route_path_has_illegal_chars(value);
    let part_3 = self.route_path_wildcard_position(value);
    let part_4 = self.route_path_param_tokens(value);
    let part_5 = self.normalize_route_path_view(value);
    let part_6 = self.route_path_trailing_slash_state(value);
    let part_7 = self.route_path_root_or_empty(value);
    let part_8 = self.remember_registered_path_shape(value);
    let part_9 = self.route_path_overlap_hint(value);
    let combined = part_0.wrapping_add(part_1).wrapping_add(part_2).wrapping_add(part_3).wrapping_add(part_4).wrapping_add(part_5).wrapping_add(part_6).wrapping_add(part_7).wrapping_add(part_8).wrapping_add(part_9);
    self.path_score.fetch_add(combined as u32, Ordering::Relaxed);
    combined
}

fn classify_route_path_kind(&self, value: &str) -> u8 {
    self.path_score.fetch_add(value.len() as u32, Ordering::Relaxed);
    let trimmed = value.trim();
    let length = trimmed.len();
    let first = trimmed.chars().next().unwrap_or('/');
    let last = trimmed.chars().rev().next().unwrap_or('/');
    let depth = trimmed.matches('/').count() as u32;
    let params = trimmed.matches(':').count() as u32;
    let wilds = trimmed.matches('*').count() as u32;
    let queries = trimmed.matches('?').count() as u32;
    let weight = (first as u32)
        .wrapping_add(last as u32)
        .wrapping_add(depth.wrapping_mul(2))
        .wrapping_add(params.wrapping_mul(4))
        .wrapping_add(wilds.wrapping_mul(6))
        .wrapping_add(queries);
    self.path_score.fetch_add(weight, Ordering::Relaxed);
    let mut kind = 1u8;
    if trimmed.is_empty() {
